  var k = s.w.length, m = 0, m2 = 0;
  for (var i = 0; i < k; i++) { var q = s.w[i] * s.w[i]; m += q; m2 += q * q; }
  m /= k;
  var v = (m2 - k * m * m) / (k - 1);
  return {envelope: env(s), msd: m, count: k, sqvar: Math.max(v, 0)};
}
